INSERT INTO `news` (`news_id`, `title`, `content`, `author_id`, `published_at`, `updated_at`, `status_id`, `image_path`) VALUES
(7, 'Руководство для новичков по Fatal Fury: City of the Wolves', '<h2>Руководство для новичков по <em>Fatal Fury: City of the Wolves</em></h2>\r\n\r\n<p><strong><em>Fatal Fury: City of the Wolves</em></strong> — новая глава легендарной серии файтингов от SNK, которая возвращает культовых бойцов и добавляет новые механики. Если вы новичок в этой игре, вот несколько советов, которые помогут вам быстрее освоиться.</p>\r\n\r\n<h3>? Основные механики</h3>\r\n<ul>\r\n    <li><strong>REV System</strong> — новая механика, позволяющая активировать усиленные версии спецприёмов.</li>\r\n    <li><strong>Just Defend</strong> — успешный блок в последний момент даёт вам преимущество для контратаки.</li>\r\n    <li><strong>Super Arts</strong> — мощные суперприёмы, которые могут изменить ход боя.</li>\r\n</ul>\r\n\r\n<h3>? Лучшие персонажи для новичков</h3>\r\n<p>Если вы только начали играть, попробуйте этих персонажей:</p>\r\n<ul>\r\n    <li><strong>Терри Богард</strong> — сбалансированный персонаж с мощными атаками и простыми комбинациями.</li>\r\n    <li><strong>Рок Ховард</strong> — универсальный стиль боя, подходит как для атаки, так и для защиты.</li>\r\n    <li><strong>Марко Родригес</strong> — эффективен в ближнем бою, прост в освоении.</li>\r\n</ul>\r\n\r\n<h3>? Советы для быстрого прогресса</h3>\r\n<ol>\r\n    <li>Начните с <strong>тренировочного режима</strong>, чтобы освоить основные комбинации.</li>\r\n    <li>Изучите <strong>кадровые преимущества</strong> (frame data), чтобы знать, когда лучше атаковать.</li>\r\n    <li>Не бойтесь экспериментировать и <strong>анализировать свои бои</strong>, пересматривая записи матчей.</li>\r\n</ol>\r\n\r\n<p><strong>Готовы испытать свои силы?</strong> Присоединяйтесь к онлайн-боям и станьте легендой <em>City of the Wolves</em>! ??</p>', 2, '2025-04-02 01:51:17', '2025-04-08 21:16:01', 2, '');

